        uint32_t save_offset;

        save_offset = ndr->offset;
        NDR_CHECK(ndr_pull_advance(ndr, (count - 1) * element_size));
        NDR_PULL_NEED_BYTES(ndr, element_size);

        for (i = 0; i < element_size; i++) {
